DROP TABLE IF EXISTS `policy_benefits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policy_benefits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `policy_id` bigint unsigned NOT NULL,
  `benefit_type` varchar(30) NOT NULL,
  `amount_type` varchar(30) NOT NULL,
  `min_amount` decimal(15,2) DEFAULT NULL,
  `max_amount` decimal(15,2) DEFAULT NULL,
  `payment_cycle` varchar(20) DEFAULT NULL,
  `duration_months` smallint unsigned DEFAULT NULL,
  `max_total_amount` decimal(15,2) DEFAULT NULL,
  `calculation_rule_json` json DEFAULT NULL,
  `display_text` varchar(500) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT (now()),
  `updated_at` datetime(6) NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `ix_policy_benefits_policy_id` (`policy_id`),
  CONSTRAINT `fk_policy_benefits_policy_id_policies` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_policy_benefits_amount_range_order` CHECK (((`min_amount` is null) or (`max_amount` is null) or (`min_amount` <= `max_amount`))),
  CONSTRAINT `ck_policy_benefits_amount_type_enum` CHECK ((`amount_type` in (_utf8mb4'FIXED',_utf8mb4'RANGE',_utf8mb4'FORMULA',_utf8mb4'VARIABLE'))),
  CONSTRAINT `ck_policy_benefits_benefit_type_enum` CHECK ((`benefit_type` in (_utf8mb4'CASH',_utf8mb4'DISCOUNT',_utf8mb4'LOAN',_utf8mb4'SAVINGS',_utf8mb4'TAX_REDUCTION',_utf8mb4'SERVICE',_utf8mb4'OTHER'))),
  CONSTRAINT `ck_policy_benefits_duration_months_positive` CHECK (((`duration_months` is null) or (`duration_months` > 0))),
  CONSTRAINT `ck_policy_benefits_max_amount_nonnegative` CHECK (((`max_amount` is null) or (`max_amount` >= 0))),
  CONSTRAINT `ck_policy_benefits_max_total_amount_nonnegative` CHECK (((`max_total_amount` is null) or (`max_total_amount` >= 0))),
  CONSTRAINT `ck_policy_benefits_min_amount_nonnegative` CHECK (((`min_amount` is null) or (`min_amount` >= 0))),
  CONSTRAINT `ck_policy_benefits_payment_cycle_enum` CHECK ((`payment_cycle` in (_utf8mb4'ONCE',_utf8mb4'MONTHLY',_utf8mb4'YEARLY',_utf8mb4'MATURITY',_utf8mb4'VARIABLE')))
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
