--
-- Table structure for table `policy_conditions`
--

DROP TABLE IF EXISTS `policy_conditions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policy_conditions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `policy_id` bigint unsigned NOT NULL,
  `condition_key` varchar(100) NOT NULL,
  `operator` varchar(30) NOT NULL,
  `expected_value_json` json DEFAULT NULL,
  `condition_group_no` smallint NOT NULL DEFAULT '1',
  `is_required` tinyint(1) NOT NULL DEFAULT '1',
  `check_mode` varchar(20) NOT NULL DEFAULT 'AUTO',
  `description` varchar(500) NOT NULL,
  `failure_message` varchar(500) DEFAULT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL DEFAULT (now()),
  `updated_at` datetime(6) NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `ix_policy_conditions_policy_id` (`policy_id`),
  CONSTRAINT `fk_policy_conditions_policy_id_policies` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_policy_conditions_check_mode_enum` CHECK ((`check_mode` in (_utf8mb4'AUTO',_utf8mb4'MANUAL',_utf8mb4'DOCUMENT'))),
  CONSTRAINT `ck_policy_conditions_condition_group_no_positive` CHECK ((`condition_group_no` > 0)),
  CONSTRAINT `ck_policy_conditions_condition_operator_enum` CHECK ((`operator` in (_utf8mb4'EQ',_utf8mb4'NE',_utf8mb4'IN',_utf8mb4'NOT_IN',_utf8mb4'GT',_utf8mb4'GTE',_utf8mb4'LT',_utf8mb4'LTE',_utf8mb4'BETWEEN',_utf8mb4'CONTAINS',_utf8mb4'EXISTS',_utf8mb4'MANUAL_CHECK'))),
  CONSTRAINT `ck_policy_conditions_sort_order_nonnegative` CHECK ((`sort_order` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

