--
-- Table structure for table `policy_documents`
--

DROP TABLE IF EXISTS `policy_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policy_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `policy_id` bigint unsigned NOT NULL,
  `document_code` varchar(50) NOT NULL,
  `document_name` varchar(255) NOT NULL,
  `required_reason` varchar(500) DEFAULT NULL,
  `issuing_organization` varchar(255) DEFAULT NULL,
  `issuing_method` varchar(500) DEFAULT NULL,
  `issuing_url` varchar(1000) DEFAULT NULL,
  `submission_format` varchar(100) DEFAULT NULL,
  `is_required` tinyint(1) NOT NULL DEFAULT '1',
  `display_order` smallint NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL DEFAULT (now()),
  `updated_at` datetime(6) NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_policy_document_code` (`policy_id`,`document_code`),
  KEY `ix_policy_documents_policy_id` (`policy_id`),
  CONSTRAINT `fk_policy_documents_policy_id_policies` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_policy_documents_display_order_nonnegative` CHECK ((`display_order` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

